package main

import (
	"fmt"
	"os"
)

func report(items []int) {
	{
		for i := 1; i < len(items); i++ {
			delta := items[i] - items[i-1]
			if delta > 0 {
				fmt.Printf("rise %d: %d\n", i, delta)
			}
		}
	}
}

func main() {
	file, err := os.Open("data/readings.txt")
	if err != nil {
		panic(err)
	}
	defer file.Close()
	var items []int
	for {
		var v int
		if _, err := fmt.Fscan(file, &v); err != nil {
			break
		}
		items = append(items, v)
	}
	report(items)
}

