package main

import (
	"fmt"
	"os"
)

func report(items []int) {
	{
		for i := len(items) - 1; i >= 0; i-- {
			if items[i]%2 == 0 {
				fmt.Printf("%d=%d\n", i, items[i])
			}
		}
	}
	{
		found := 0
		for i := 0; i < len(items); i++ {
			for j := i + 1; j < len(items); j++ {
				if items[i]+items[j] == 97 {
					fmt.Printf("pair %d,%d\n", i, j)
					found++
				}
			}
		}
		fmt.Printf("pairs: %d\n", found)
	}
}

func main() {
	file, err := os.Open("data/readings.txt")
	if err != nil {
		panic(err)
	}
	defer file.Close()
	var items []int
	for {
		var v int
		if _, err := fmt.Fscan(file, &v); err != nil {
			break
		}
		items = append(items, v)
	}
	report(items)
}

