"""Reads the sensor readings and prints a few summaries."""


def report(items):
    for i in range(len(items) - 1, 0 - 1, -1):
        if items[i] % 2 == 0:
            print(f"{i}={items[i]}")
    size = 2
    for i in range(0, len(items), size):
        print(f"batch {i // size}: {sum(items[i:i + size])}")


if __name__ == "__main__":
    with open("data/readings.txt") as handle:
        report([int(x) for x in handle.read().split()])
